head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setCellMaxLength]<br/>inputType=\"custom\" 인 Column 의 특정 Body Cell 에 입력 가능한 최대 길이를 설정합니다.",
    "validation" : [
        "rowIndex(필수) 파라미터는 Body 가 MultiLine 일때 각 Line 의 Row 인덱스값은 같습니다.",
        "columnInfo(필수) 파라미터는 Row 가 MultiLine 이어도 모든 Column 은 고유의 인덱스값을 갖습니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제] Body 컬럼은 inputType=custom + typeGetter(Cell inputType=text). Body 가 MultiLine(2줄).\n[MultiLine] 한 데이터 Row 가 2줄 표시 -> 두 줄은 같은 rowIndex, Column 은 0~3 고유 인덱스 (1줄 col1(0)/col2(1), 2줄 col3(2)/col4(3)).\n[절차] rowIndex / columnIndex / maxLength 선택 -> setCellMaxLength 실행.\n[확인] 편집모드 진입 시 maxLength 길이 제한이 적용되어 기존 데이터가 설정값 길이로 잘림 (같은 rowIndex 라도 columnIndex 로 위/아래 Line 셀 개별 지정)."', '', 'label1');

    // dataList 생성 + 초기값 바인딩
    //  MultiLine 검증 : 한 데이터 Row 가 2줄에 걸쳐 표시되며 두 줄은 동일 rowIndex, Column 은 0~3 고유 인덱스를 가짐.
    $c.gcm.createBasicDataList('', '', 'dlt_bind');
    dlt_bind.setJSON([
        { "col1": "1234567890", "col2": "987654321", "col3": "246813579", "col4": "13579.2468" },
        { "col1": "5566778899", "col2": "112233445", "col3": "678901234", "col4": "98765.4321" }
    ]);

    // target 생성
    //  4개 컬럼 모두 inputType=custom + typeGetter 로 Cell 의 inputType=text 구성 (setCellMaxLength 적용 대상)
    // ★ MultiLine : gBody 에 2개의 row 를 두어 한 데이터 Row 가 2줄에 걸쳐 표시되게 한다.
    //  - 1줄 : col1(idx0) / col2(idx1)
    //  - 2줄 : col3(idx2) / col4(idx3)
    //  - 두 줄은 동일 rowIndex, Column 은 줄에 걸쳐 0~3 고유 인덱스
    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' checkAllType="false" dataList="data:dlt_bind" id="" ev:onafteredit="scwin.target1_onafteredit" style="width:560px;height:300px;">';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="280" inputType="text" id="hcol1" value="col1 (idx0)"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol2" value="col2 (idx1)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="hrow2">';
    strTarget += '<w2:column width="280" inputType="text" id="hcol3" value="col3 (idx2)"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol4" value="col4 (idx3)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="280" inputType="custom" id="col1" dataList="col1" typeGetter="scwin.target1_typeGetter"></w2:column>';
    strTarget += '<w2:column width="*" inputType="custom" id="col2" dataList="col2" typeGetter="scwin.target1_typeGetter"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="brow2">';
    strTarget += '<w2:column width="280" inputType="custom" id="col3" dataList="col3" typeGetter="scwin.target1_typeGetter"></w2:column>';
    strTarget += '<w2:column width="*" inputType="custom" id="col4" dataList="col4" typeGetter="scwin.target1_typeGetter"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
}



// 각 Cell 을 inputType=text (allow-list) 로 구성 (setCellMaxLength 적용 대상)
scwin.target1_typeGetter = function (info) {
    return { id: 'cell_' + info.rowIndex + '_' + info.colIndex, inputType: 'text', options: {} };
};



// setCellMaxLength 실행 : 특정 셀에 최대 입력 길이를 설정한다.
//  MultiLine : 같은 rowIndex 라도 고유 columnIndex(0~3)로 위/아래 Line 의 Cell 을 각각 지정할 수 있다.
//  실제 효과(maxLength 잘림)는 해당 셀을 더블클릭하여 편집모드로 긴 값을 입력한 뒤
//  포커스아웃 시 발생하는 onafteredit 에서 셀에 표시된 값으로 확인한다.
scwin.btn_setCellMaxLength_onclick = function () {
    let rowIndex = Number(par_rowIndex.getValue());
    let columnIndex = Number(par_columnIndex.getValue());
    let maxLengthVal = Number(par_maxLength.getValue());

    let ret = scwin.target1.setCellMaxLength(rowIndex, columnIndex, maxLengthVal);

    wf_body_bottom.getObj("scwin").setReturnValue(
        "setCellMaxLength(" + rowIndex + ", " + columnIndex + ", " + maxLengthVal + ")"
        + (ret === false ? " -> 전제 미충족(미동작)" : " -> 설정 완료. 해당 셀을 편집하여 maxLength 잘림을 확인하세요."));
}



// onafteredit : 셀 편집모드가 종료되어 포커스가 빠져나온 시점에 발생.
//  편집 종료된 셀에 실제 표시된 값(maxLength 적용으로 잘린 결과)을 조회하여 출력한다.
//  MultiLine 이므로 같은 rowIndex 라도 columnIndex(0~3)로 위/아래 Line 셀을 구분 표기한다.
scwin.target1_onafteredit = function (rowIndex, columnIndex, value) {
    // getCellData 는 colID 인자에 컬럼 인덱스를 직접 받아 내부에서 getColumnID 로 해석한다.
    let displayed = scwin.target1.getCellData(rowIndex, columnIndex);

    wf_body_bottom.getObj("scwin").setReturnValue(
        "onafteredit | rowIndex : " + rowIndex + ", columnIndex : " + columnIndex
        + " -> 셀 표시값 : \"" + displayed + "\" (길이 " + String(displayed).length + ")");
}
